use gearth_rust::settings::Settings;
use std::{fs,path::PathBuf};
fn path()->PathBuf {let mut random=[0;8];getrandom::fill(&mut random).unwrap();std::env::temp_dir().join(format!("gearth-settings-{:016x}.json",u64::from_be_bytes(random)))}
#[test] fn save_replace_load_and_preserve_unknown_fields() {let path=path();let mut settings=Settings::default();settings.values.insert("remote".into(),"test.example:30000".into());settings.extra.insert("future_field".into(),serde_json::json!({"keep":true}));settings.save(&path).unwrap();settings.values.insert("remote".into(),"second.example:30001".into());settings.save(&path).unwrap();let loaded=Settings::read(&path).unwrap();assert_eq!(loaded.get("remote"),"second.example:30001");assert_eq!(loaded.extra["future_field"]["keep"],true);fs::remove_file(path).unwrap();}
#[test] fn malformed_config_is_rejected_without_overwriting() {let path=path();fs::write(&path,"{broken").unwrap();assert!(Settings::read(&path).is_err());assert_eq!(fs::read_to_string(&path).unwrap(),"{broken");fs::remove_file(path).unwrap();}
#[test] fn imports_real_beta29_cache_keys_and_retains_all_original_values() {let mut settings=Settings::default();let original=serde_json::json!({"last_connection_settings":{"host":"game.example","port":30000,"auto_detect":false},"last_client_mode":"FLASH","socks_config":{"ip":"127.0.0.1","port":1080},"notepad_text":"hello","unknown":42});settings.import_java_cache(original.clone()).unwrap();assert_eq!(settings.get("remote"),"game.example:30000");assert_eq!(settings.get("socks_proxy"),"127.0.0.1:1080");assert_eq!(settings.extra["legacy_java_cache"],original);}
